arcanas = [
    {"id": 0, "nome": "Fool (Tolo)", "descricao": "A Arcana do Tolo não significa que pode ser tomada levianamente. O Tolo é o número zero. Ele é o vazio do qual todas as outras coisas começam."},
    {"id": 1, "nome": "Magician (Mágico)", "descricao": "No momento que o homem devorou o fruto do conhecimento, ele selou seu destino...\nConfiando seu futuro às cartas, o homem se agarra a uma esperança fraca.\nSim, as Arcana são os meios pelos quais tudo é revelado...\nPara alguém atingir seu sonho são exigidas uma vontade severa e uma determinação infalível."},
    {"id": 2, "nome": "Priestess (Sacerdotisa)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nA voz silenciosa dentro do coração de alguém sussura a mais profunda sabedoria."},
    {"id": 3, "nome": "Empress (Imperatriz)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nCelebrem a grandeza da vida...seu brilho...sua magnificência..."},
    {"id": 4, "nome": "Emperor (Imperador)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nSomente coragem frente à dúvida pode levar alguém à resposta..."},
    {"id": 5, "nome": "Hierophant (Hierofante)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nÉ verdadeiramente um dom precioso entender as forças que guiam a si próprio..."},
    {"id": 6, "nome": "Lovers (Amantes)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nHá ambas alegria e maravilha em chegar a entender outro..."},
    {"id": 7, "nome": "Chariot (Carruagem)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nUma das maiores bênçãos da vida é a liberdade para alguém perseguir seus objetivos."},
    {"id": 8, "nome": "Justice (Justiça)", "descricao": "As Arcana são os meios pelos quais tudo é revelado.\nPara achar o único caminho verdadeiro, alguém deve buscar orientação em meio à incerteza..."},
    {"id": 9, "nome": "Hermit (Ermitão)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nÉ exigida grande coragem para olhar a si mesmo honestamente, e forjar seu próprio caminho..."},
    {"id": 10, "nome": "Fortune (Fortuna)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nAo lado do tempo existe o destino, o portador da crueldade."},
    {"id": 11, "nome": "Strength (Força)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nApenas com força alguém pode suportar sofrimento e tormenta."},
    {"id": 12, "nome": "Hanged Man (Enforcado)", "descricao": "As Arcana são os meios pelos quais tudo é revelado...\nFace ao desastre jaz a oportunidade para renovação."},
    {"id": 13, "nome": "Death (Morte)", "descricao": "No momento que o homem devorou o fruto do conhecimento, ele selou seu destino...\nConfiando seu futuro às cartas, o homem se agarra a uma esperança fraca.\nSim, as Arcana são os meios pelos quais tudo é revelado...\nAlém do caminho batido jaz o fim absoluto. Não importa quem você é...\nMorte te espera."},
    {"id": 14, "nome": "Temperance (Temperança)", "descricao": "Retratada como uma mulher com asas de anjo misturando a água de dois copos, um azul e o outro vermelho, a Arcana da Temperança é um símbolo de síntese, prudência, harmonia e união de opostos."},
    {"id": 15, "nome": "Devil (Diabo)", "descricao": "Retratada como um demônio hermafrodita acima de duas figuras nuas acorrentadas, o aspecto negativo da Arcana do Diabo representa a vontade de fazer coisas egoístas, impulsivas e violentas e ser um escravo de seus próprios impulsos e sentimentos.\nOcasionalmente, ela também é considerada um símbolo de tentação.\nO aspecto positivo, entretanto, representa um laço ou comprometimento saudável."},
    {"id": 16, "nome": "Tower (Torre)", "descricao": "Retratada como uma torre acertada por um raio, da qual duas pequenas figuras caem;\né uma alegoria estrita da Torre de Babel sobre o orgulho preceder a queda."},
    {"id": 17, "nome": "Star (Estrela)", "descricao": "É uma carta forte, uma que dá esperança a aqueles no chão abaixo. Ela brilha nos tempos de necessidade. Mas, eventualmente, está destinada a cair na terra e desaparecer...\nMesmo eu posso sentir a tristeza desse destino inescapável..."},
    {"id": 18, "nome": "Moon (Lua)", "descricao": "Retratada como dois cachorros uivando para a lua ao redor de uma poça que tem uma lagosta dentro, com duas torres ao fundo, a Arcana da Lua é associada com criatividade, inspiração, sonhos, loucura, ilusões, medo, fantasia, o subconsciente e truques."},
    {"id": 19, "nome": "Sun (Sol)", "descricao": "Retratada como duas crianças de mãos dadas sob um sol ardente, a Arcana do Sol simboliza felicidade, alegria, energia, otimismo e realização. Ocasionalmente, ela é também associada com a felicidade inicial da pessoa."},
    {"id": 20, "nome": "Judgment (Julgamento)", "descricao": "A Arcana do Julgamento, no tarô, é associada com realizar a sua vocação, ganhar um entendimento profundo da vida e um sentimento de aceitação e absolvição."},
    {"id": 21, "nome": "World (Mundo)", "descricao": "Ela frequentemente aparece como a Arcana do triunfo final, criando milagres e ajudando os protagonistas.\nRetratada como uma jovem mulher (ou andrógina, dependendo do baralho) cercada pelas figuras de um anjo, um touro, uma águia e um leão, a Arcana do Mundo é uma representação da totalidade do mundo, o símbolo de cumprimento, plenitude e harmonia."}
]

